create extension if not exists pgcrypto;create type public.app_role as enum('admin','manager','data_entry','viewer');create type public.outgoing_type as enum('sale','employee','mortality','adjustment');create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'data_entry',created_at timestamptz not null default now());create table public.farm_receipts(id uuid primary key default gen_random_uuid(),received_at timestamptz not null,farm_name text not null,reference_no text,farm_count integer not null check(farm_count>=0),farm_weight numeric(12,2) not null check(farm_weight>=0),notes text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now());create table public.shop_receiving(id uuid primary key default gen_random_uuid(),receipt_id uuid not null references public.farm_receipts(id),received_at timestamptz not null,live_count integer not null check(live_count>=0),live_weight numeric(12,2) not null check(live_weight>=0),mortality_count integer not null default 0 check(mortality_count>=0),mortality_weight numeric(12,2) not null default 0 check(mortality_weight>=0),notes text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),unique(receipt_id));create table public.rates(id uuid primary key default gen_random_uuid(),effective_at timestamptz not null,category text not null check(category in('big','small','other','employee')),rate_per_kg numeric(12,4) not null check(rate_per_kg>=0),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now());create table public.outgoing_events(id uuid primary key default gen_random_uuid(),occurred_at timestamptz not null,event_type public.outgoing_type not null,category text not null default 'other' check(category in('big','small','other')),bird_count integer not null check(bird_count>=0),weight_kg numeric(12,2) not null check(weight_kg>=0),rate_per_kg numeric(12,4),reference_no text,notes text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),check((event_type='sale' and rate_per_kg is not null) or event_type<>'sale'));create table public.audit_log(id bigint generated always as identity primary key,created_at timestamptz not null default now(),user_id uuid,action text not null,table_name text not null,record_id uuid,old_data jsonb,new_data jsonb);create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email));return new;end$$;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;create or replace function public.can_write() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role in('admin','manager','data_entry'))$$;alter table public.profiles enable row level security;alter table public.farm_receipts enable row level security;alter table public.shop_receiving enable row level security;alter table public.rates enable row level security;alter table public.outgoing_events enable row level security;alter table public.audit_log enable row level security;create policy p1 on public.profiles for select using(id=auth.uid() or public.is_admin());create policy p2 on public.profiles for all using(public.is_admin()) with check(public.is_admin());create policy r1 on public.farm_receipts for select using(auth.uid() is not null);create policy r2 on public.farm_receipts for insert with check(public.can_write());create policy r3 on public.farm_receipts for update using(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager')) with check(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager'));create policy r4 on public.farm_receipts for delete using(public.is_admin());create policy s1 on public.shop_receiving for select using(auth.uid() is not null);create policy s2 on public.shop_receiving for insert with check(public.can_write());create policy s3 on public.shop_receiving for update using(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager')) with check(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager'));create policy s4 on public.shop_receiving for delete using(public.is_admin());create policy t1 on public.rates for select using(auth.uid() is not null);create policy t2 on public.rates for insert with check(public.can_write());create policy t3 on public.rates for update using(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager')) with check(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager'));create policy o1 on public.outgoing_events for select using(auth.uid() is not null);create policy o2 on public.outgoing_events for insert with check(public.can_write());create policy o3 on public.outgoing_events for update using(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager')) with check(public.is_admin() or exists(select 1 from public.profiles where id=auth.uid() and role='manager'));create policy o4 on public.outgoing_events for delete using(public.is_admin());create policy a1 on public.audit_log for select using(public.is_admin());create or replace function public.audit_trigger() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then insert into public.audit_log(user_id,action,table_name,record_id,new_data) values(auth.uid(),tg_op,tg_table_name,new.id,to_jsonb(new));return new;elsif tg_op='UPDATE' then insert into public.audit_log(user_id,action,table_name,record_id,old_data,new_data) values(auth.uid(),tg_op,tg_table_name,new.id,to_jsonb(old),to_jsonb(new));return new;else insert into public.audit_log(user_id,action,table_name,record_id,old_data) values(auth.uid(),tg_op,tg_table_name,old.id,to_jsonb(old));return old;end if;end$$;create trigger audit_receipts after insert or update or delete on public.farm_receipts for each row execute function public.audit_trigger();create trigger audit_receiving after insert or update or delete on public.shop_receiving for each row execute function public.audit_trigger();create trigger audit_rates after insert or update or delete on public.rates for each row execute function public.audit_trigger();create trigger audit_outgoing after insert or update or delete on public.outgoing_events for each row execute function public.audit_trigger();create or replace function public.daily_reconciliation(p_date date) returns table(received_count bigint,received_weight numeric,live_count bigint,live_weight numeric,mortality_count bigint,mortality_weight numeric,employee_count bigint,employee_weight numeric,sold_count bigint,sold_weight numeric,sales_amount numeric,expected_sales numeric,count_difference numeric,weight_difference numeric,sales_difference numeric,live_avg_weight numeric,employee_avg_weight numeric) language sql stable security invoker as $$with r as(select coalesce(sum(farm_count),0)::bigint c,coalesce(sum(farm_weight),0)::numeric w from farm_receipts where received_at::date=p_date),s as(select coalesce(sum(live_count),0)::bigint c,coalesce(sum(live_weight),0)::numeric w,coalesce(sum(mortality_count),0)::bigint mc,coalesce(sum(mortality_weight),0)::numeric mw from shop_receiving where received_at::date=p_date),o as(select coalesce(sum(bird_count) filter(where event_type='sale'),0)::bigint sc,coalesce(sum(weight_kg) filter(where event_type='sale'),0)::numeric sw,coalesce(sum(bird_count) filter(where event_type='employee'),0)::bigint ec,coalesce(sum(weight_kg) filter(where event_type='employee'),0)::numeric ew,coalesce(sum(weight_kg*rate_per_kg) filter(where event_type='sale'),0)::numeric sa)select r.c,r.w,s.c,s.w,s.mc,s.mw,o.ec,o.ew,o.sc,o.sw,o.sa,o.sa,(s.c-o.ec-o.sc)::numeric,(s.w-s.mw-o.ew-o.sw)::numeric,0::numeric,case when s.c>0 then round(s.w/s.c,4) else 0 end,case when o.ec>0 then round(o.ew/o.ec,4) else 0 end from r,s,o$$;create or replace function public.monthly_reconciliation(p_month text) returns table(received_count bigint,received_weight numeric,live_count bigint,live_weight numeric,mortality_count bigint,mortality_weight numeric,employee_count bigint,employee_weight numeric,sold_count bigint,sold_weight numeric,sales_amount numeric,expected_sales numeric,count_difference numeric,weight_difference numeric,sales_difference numeric,live_avg_weight numeric,employee_avg_weight numeric) language sql stable security invoker as $$with b as(select to_date(p_month,'YYYY-MM') a,(to_date(p_month,'YYYY-MM')+interval '1 month')::date z),r as(select coalesce(sum(farm_count),0)::bigint c,coalesce(sum(farm_weight),0)::numeric w from farm_receipts,b where received_at>=a and received_at<z),s as(select coalesce(sum(live_count),0)::bigint c,coalesce(sum(live_weight),0)::numeric w,coalesce(sum(mortality_count),0)::bigint mc,coalesce(sum(mortality_weight),0)::numeric mw from shop_receiving,b where received_at>=a and received_at<z),o as(select coalesce(sum(bird_count) filter(where event_type='sale'),0)::bigint sc,coalesce(sum(weight_kg) filter(where event_type='sale'),0)::numeric sw,coalesce(sum(bird_count) filter(where event_type='employee'),0)::bigint ec,coalesce(sum(weight_kg) filter(where event_type='employee'),0)::numeric ew,coalesce(sum(weight_kg*rate_per_kg) filter(where event_type='sale'),0)::numeric sa from outgoing_events,b where occurred_at>=a and occurred_at<z)select r.c,r.w,s.c,s.w,s.mc,s.mw,o.ec,o.ew,o.sc,o.sw,o.sa,o.sa,(s.c-o.ec-o.sc)::numeric,(s.w-s.mw-o.ew-o.sw)::numeric,0::numeric,case when s.c>0 then round(s.w/s.c,4) else 0 end,case when o.ec>0 then round(o.ew/o.ec,4) else 0 end from r,s,o$$;